/* @author MILO-GAO(高振銘)@2020 */ package page2020.unit;import java.util.ArrayList;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;import page2020.core.App;import page2020.core.Form;import page2020.core.Page;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.C3;import page2020.view.Element;import page2020.view.H5;import page2020.view.Value;import page2020.view.bs4.B4button;import page2020.view.bs4.B4button.BtnColor;import page2020.view.bs4.B4dropdown;import page2020.view.bs4.B4inputGroup;import page2020.view.bs4.B4nav;import page2020.view.bs4.B4navbar;import page2020.view.bs4.B4show.D;import page2020.view.bs4.B4show.P;import page2020.view.bs4.B4text.TextX;import page2020.view.css3.C3color.White;import page2020.view.css3.C3font.Weight;import page2020.view.html5.H5a;import page2020.view.html5.H5span;import secure2020.data.SecureUser;public class Unavbar extends B4navbar {	private static final String function = "func";	private Map<String, Value[]> selectors = new LinkedHashMap<String, Value[]>();	public Unavbar(String sysCode) {		super.name(PageKey.navbar);		final Page page = App.sysPage(sysCode);			super.expend(1).cssClass(P.fixTop)			.brand(H5.a().href("./" + sysCode).append(				B4.image().src(page.getLogo()[1]),				B4.image().src(page.getLogo()[0]).cssClass(D.none)			), "50px")			.header(H5.span().code(App.sysCodeKey(sysCode))				.css(C3.font.size("22px"), C3.font.weight(Weight.bold)))			.toggler()			.nav();		List<Menu> topList = this.topList(sysCode);		if (EmptyUtil.not(topList)) {			topList.forEach(menu -> super.item(this.dropdown(menu)));		}		H5span tools = H5.span().name(PageKey.tools).cssClass(P.mlAuto, TextX.nowrap);		super.boxes().append(tools);		String tip = page.getSearchTipCode();		if (EmptyUtil.not(tip)) {			tools.append(H5.span().cssClass(D.inlineBlock).append(this.search(tip)));		}		String[] langs = page.getLangs();		if (EmptyUtil.not(langs)) {			tools.append(H5.span().cssClass(D.inlineBlock).append(this.users(langs)));		}		this.color(page.getBarColor(), page.getBarBg());	}	public Unavbar personal(List<String> favorites) {		B4nav nav = (B4nav) super.find(null, "ul", B4navbar.nav);		int index = 0;		while (index < nav.count()) {			B4dropdown dropdown = (B4dropdown) nav.get(index);			Element<?, ?> menu = (Element<?, ?>) dropdown.get(1);			int i = 0;			while (i < menu.count()) {				H5a a = (H5a) menu.get(i);				String name = (String) a.getData(function);				if (! favorites.contains(name)) {					menu.remove(i);				} else {					i += 1;				}			}			if (menu.count() == 0) {				nav.remove(index);			} else {				index += 1;			}		}		return this;	}	public Unavbar selector(Page page) {		if (! this.selectors.isEmpty()) {			this.selectors.forEach((key, value) -> page.selector(key, value));		}		return this;	}	public void fullname(SecureUser user) {		B4dropdown users = (B4dropdown) super.find(PageKey.users);		if (users != null) {			B4button button = (B4button) users.get(0);			button.empty();			button.append(H5.span().text(user.getFullname()));			if (EmptyUtil.not(user.getTitle())) {				button.append(H5.span().text(user.getTitle()));			}		}	}	@Override	public Unavbar copy() {		Unavbar bean = (Unavbar) super.copy();		bean.setSelectors(new LinkedHashMap<String, Value[]>(this.selectors));		return bean;	}	private List<Menu> topList(String sysCode) {		Map<String, Menu> topMap = new LinkedHashMap<String, Menu>();		App.menuProp.getData().forEach((key, menu) -> {			if (menu.getSysCode().equals(sysCode) && menu.getLevel() == 1) {				topMap.put(key, menu.copy());			}		});		if (topMap.isEmpty()) {			if (App.menuProp.hasKey(sysCode)) {				topMap.put(sysCode, App.menuProp.value(sysCode).copy());			} else {				return new ArrayList<Menu>();			}		}		App.menuProp.getData().forEach((key, menu) -> {			if (menu.getSysCode().equals(sysCode) && menu.getLevel() >= 2 && (! menu.getFuncList().isEmpty())) {				for (String topKey : topMap.keySet()) {					if (key.startsWith(topKey)) {						topMap.get(topKey).getFuncList().addAll(menu.getFuncList());						break;					}				}			}		});		List<Menu> topList = new ArrayList<Menu>();		topMap.forEach((key, menu) -> {			if (! menu.getFuncList().isEmpty()) {				topList.add(menu);			}		});		return topList;	}	private B4dropdown dropdown(Menu menu) {		B4dropdown dropdown = B4.dropdown()			.a(H5.a().code(menu.getCode()))			.menu();		menu.getFuncList().forEach(func -> {			H5a a = H5.a().data(function, func.getName()).href(func.getAction());			if (EmptyUtil.not(func.getIcon())) {				a.icon(func.getIcon());			} else {				a.append(App.icon("menu.link"));			}			a.append(H5.span().cssClass("ml-1").code(func.getCode()));			dropdown.item(a);		});		return dropdown;	}	private B4dropdown users(String[] langs) {		B4dropdown users = B4.dropdown()			.name(PageKey.users)			.button(false, B4.button().css(C3.font.weight(Weight.bold)))			.menu(true)				.item(B4.button(BtnColor.link).data(PageKey.tool, "logout").icon("sign-out-alt").append(					H5.span().cssClass("ml-1").code("page2020.tool.logout")))				.divider();		for (int i=0; i < langs.length; i++) {			users.item(B4.button(BtnColor.link)				.data(PageKey.lang, langs[i]).icon("language").append(					H5.span().cssClass("ml-1").code("page2020.lang." + langs[i])));		}		this.selectors.put("div[data-name='" + PageKey.navbar + "'] button[disabled]",			new Value[] { C3.color(White.White), C3.color.opacity(1.0) });		return users;	}	private B4inputGroup search(String tip) {		B4inputGroup search = (B4inputGroup) B4.inputGroup()			.name(PageKey.search)			.css(C3.width("15rem"), C3.box.minWidth("10rem"))			.control(B4.input().name(PageKey.search))			.after().append(B4.button().append(App.icon("search")))			.boxes();		search.add(1, Form.tip(tip));		return search;	}	private Unavbar color(String color, String background) {		super.boxes().css(C3.color(color), C3.bg(background));		String dropdownE = "nav[data-name='" + PageKey.navbar + "'] ";		this.selectors.put(dropdownE + "a.dropdown-toggle:link", new Value[] { C3.color(color) });		this.selectors.put(dropdownE + "a", new Value[] { C3.margin("none") });		Element<?, ?> nav = (Element<?, ?>) super.get(3);		nav.css(C3.bg(background));		B4dropdown users = (B4dropdown) super.find(PageKey.users);		if (users != null) {			users.boxes();			B4button button = (B4button) users.get(0);			button.css(C3.color(color), C3.bg(background));		}		B4inputGroup search = (B4inputGroup) super.find(PageKey.search);		if (search != null) {			B4button button = (B4button) search.find(null, "button", null);			button.css(C3.bg(color), C3.color(background));		}		return this;	}	public Map<String, Value[]> getSelectors() {		return selectors;	}	public void setSelectors(Map<String, Value[]> selectors) {		this.selectors = selectors;	}}